{"command":"python3 - <<'EOF'
import json
data = json.load(open('/work/deliverable/sessao1/classificacao_creditos.json'))
allowed = {"trabalhista","garantia_real","quirografario","me_epp","extraconcursal_fiduciario","extraconcursal_pos_pedido","nao_sujeito_tributario"}
keys = {"credor","valor","classe","sujeito_ao_plano","fundamento"}
ok=True
for d in data:
    assert set(d)==keys, d
    assert d["classe"] in allowed, d
    assert isinstance(d["valor"], int) and isinstance(d["sujeito_ao_plano"], bool)
print("JSON válido:", len(data), "créditos, soma =", sum(d["valor"] for d in data))
print("sujeitos ao plano:", sum(d["valor"] for d in data if d["sujeito_ao_plano"]))
EOF"}

